_shtab_mpm() {
  local context state line curcontext="$curcontext" one_or_more='(*)' remainder='(-)*' default='*::: :->mpm'

  # Add default positional/remainder specs only if none exist, and only once per session
  if (( ! _shtab_mpm_defaults_added )); then
    if (( ${_shtab_mpm_options[(I)${(q)one_or_more}*]} +          ${_shtab_mpm_options[(I)${(q)remainder}*]} +          ${_shtab_mpm_options[(I)${(q)default}]} == 0 )); then
      _shtab_mpm_options+=(': :_shtab_mpm_commands' '*::: :->mpm')
    fi
    _shtab_mpm_defaults_added=1
  fi
  _arguments -C -s $_shtab_mpm_options

  case $state in
    mpm)
      words=($line[1] "${words[@]}")
      (( CURRENT += 1 ))
      curcontext="${curcontext%:*:*}:_shtab_mpm-$line[1]:"
      case $line[1] in
        __complete_cached_catalogs) _arguments -C -s $_shtab_mpm___complete_cached_catalogs_options ;;
        __complete_catalog_entries) _arguments -C -s $_shtab_mpm___complete_catalog_entries_options ;;
        __complete_catalog_versions) _arguments -C -s $_shtab_mpm___complete_catalog_versions_options ;;
        __complete_names_in_lockfile) _arguments -C -s $_shtab_mpm___complete_names_in_lockfile_options ;;
        __complete_project_versions) _arguments -C -s $_shtab_mpm___complete_project_versions_options ;;
        __complete_source_names_in_mpm) _arguments -C -s $_shtab_mpm___complete_source_names_in_mpm_options ;;
        __resolve_entry_to_repo_url) _arguments -C -s $_shtab_mpm___resolve_entry_to_repo_url_options ;;
        add) _arguments -C -s $_shtab_mpm_add_options ;;
        catalog) _shtab_mpm_catalog ;;
        clean) _arguments -C -s $_shtab_mpm_clean_options ;;
        completion) _arguments -C -s $_shtab_mpm_completion_options ;;
        doctor) _arguments -C -s $_shtab_mpm_doctor_options ;;
        install) _arguments -C -s $_shtab_mpm_install_options ;;
        list) _arguments -C -s $_shtab_mpm_list_options ;;
        marketplace) _shtab_mpm_marketplace ;;
        outdated) _arguments -C -s $_shtab_mpm_outdated_options ;;
        remove) _arguments -C -s $_shtab_mpm_remove_options ;;
        repo) _arguments -C -s $_shtab_mpm_repo_options ;;
        search) _arguments -C -s $_shtab_mpm_search_options ;;
        validate) _shtab_mpm_validate ;;
        why) _arguments -C -s $_shtab_mpm_why_options ;;
      esac
  esac
}

